package com.orderflow.notification.security;import java.util.List;import org.springframework.security.oauth2.core.*;import org.springframework.security.oauth2.jwt.Jwt;public class RequiredJwtClaimsValidator implements OAuth2TokenValidator<Jwt>{private static final OAuth2Error E=new OAuth2Error("invalid_token","Required access-token claims are missing",null);public OAuth2TokenValidatorResult validate(Jwt j){List<String>r=j.getClaimAsStringList("roles");boolean v=j.getSubject()!=null&&j.getId()!=null&&j.getIssuedAt()!=null&&j.getExpiresAt()!=null&&j.hasClaim("token_version")&&r!=null&&!r.isEmpty();return v?OAuth2TokenValidatorResult.success():OAuth2TokenValidatorResult.failure(E);}}
